const nums = [-2, -10, 1];
const ref = nums.sort();
const words = ["b", "a", "c"].toSorted((x, y) => x - y);
const mixed = [undefined, 4, 9].toSorted((x, y) => y - x);

console.log(nums.join(","));
console.log(ref === nums);
console.log(words.join(","));
console.log(mixed.map(String).join(","));
